import {
  useEffect,
  useState,
} from "react";

import {
  createProduct,
  getProductById,
  updateProduct,
} from "../services/productService.js";

const emptyForm = {
  name: "",
  description: "",
  price: "",
  compareAtPrice: "",
  stock: "",
  category: "general",
  imageUrl: "",
  isActive: true,
};

const ProductForm = ({
  productId,
  onSaved,
  onCancel,
}) => {
  const isEditing = Boolean(productId);

  const [
    form,
    setForm,
  ] = useState(emptyForm);

  const [
    loading,
    setLoading,
  ] = useState(isEditing);

  const [
    saving,
    setSaving,
  ] = useState(false);

  const [
    error,
    setError,
  ] = useState("");

  const [
    success,
    setSuccess,
  ] = useState("");

  useEffect(() => {
    if (!productId) {
      return;
    }

    const loadProduct = async () => {
      try {
        setLoading(true);
        setError("");

        const data =
          await getProductById(productId);

        const product = data.product;

        setForm({
          name: product.name || "",
          description:
            product.description || "",
          price:
            product.price?.toString() || "",
          compareAtPrice:
            product.compareAtPrice === null ||
            product.compareAtPrice === undefined
              ? ""
              : product.compareAtPrice.toString(),
          stock:
            product.stock?.toString() || "",
          category:
            product.category || "general",
          imageUrl:
            product.imageUrl ||
            product.images?.[0] ||
            "",
          isActive:
            product.isActive !== false,
        });
      } catch (requestError) {
        setError(
          requestError.message ||
            "Unable to load product"
        );
      } finally {
        setLoading(false);
      }
    };

    loadProduct();
  }, [productId]);

  const handleChange = (event) => {
    const {
      name,
      value,
      type,
      checked,
    } = event.target;

    setForm((currentForm) => ({
      ...currentForm,
      [name]:
        type === "checkbox"
          ? checked
          : value,
    }));
  };

  const validateForm = () => {
    if (!form.name.trim()) {
      return "Product name is required";
    }

    if (!form.description.trim()) {
      return "Product description is required";
    }

    if (
      form.price === "" ||
      Number.isNaN(Number(form.price)) ||
      Number(form.price) < 0
    ) {
      return "Enter a valid price";
    }

    if (
      form.stock === "" ||
      Number.isNaN(Number(form.stock)) ||
      Number(form.stock) < 0 ||
      !Number.isInteger(Number(form.stock))
    ) {
      return "Stock must be a whole number";
    }

    if (
      form.compareAtPrice !== "" &&
      (
        Number.isNaN(
          Number(form.compareAtPrice)
        ) ||
        Number(form.compareAtPrice) < 0
      )
    ) {
      return "Enter a valid comparison price";
    }

    return "";
  };

  const handleSubmit = async (
    event
  ) => {
    event.preventDefault();

    const validationError =
      validateForm();

    if (validationError) {
      setError(validationError);
      return;
    }

    try {
      setSaving(true);
      setError("");
      setSuccess("");

      const productData = {
        name: form.name.trim(),
        description:
          form.description.trim(),
        price: Number(form.price),
        compareAtPrice:
          form.compareAtPrice === ""
            ? null
            : Number(form.compareAtPrice),
        stock: Number(form.stock),
        category:
          form.category.trim().toLowerCase() ||
          "general",
        imageUrl:
          form.imageUrl.trim(),
        isActive: form.isActive,
      };

      if (isEditing) {
        await updateProduct(
          productId,
          productData
        );

        setSuccess(
          "Product updated successfully"
        );
      } else {
        await createProduct(
          productData
        );

        setSuccess(
          "Product created successfully"
        );

        setForm(emptyForm);
      }

      if (onSaved) {
        await onSaved();
      }
    } catch (requestError) {
      setError(
        requestError.message ||
          "Unable to save product"
      );
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <p>Loading product...</p>
    );
  }

  return (
    <form
      className="product-form"
      onSubmit={handleSubmit}
    >
      <div className="product-form__header">
        <div>
          <p className="eyebrow">
            {isEditing
              ? "Edit inventory"
              : "New inventory"}
          </p>

          <h2>
            {isEditing
              ? "Edit product"
              : "Add product"}
          </h2>
        </div>

        {onCancel && (
          <button
            type="button"
            className="button button--ghost"
            onClick={onCancel}
          >
            Cancel
          </button>
        )}
      </div>

      {error && (
        <p
          className="form-message form-message--error"
          role="alert"
        >
          {error}
        </p>
      )}

      {success && (
        <p
          className="form-message form-message--success"
          role="status"
        >
          {success}
        </p>
      )}

      <div className="form-grid">
        <label className="form-field form-field--wide">
          <span>Product name</span>
          <input
            name="name"
            value={form.name}
            onChange={handleChange}
            placeholder="Classic Cotton T-Shirt"
            maxLength={120}
            required
          />
        </label>

        <label className="form-field form-field--wide">
          <span>Description</span>
          <textarea
            name="description"
            value={form.description}
            onChange={handleChange}
            placeholder="Describe your product..."
            maxLength={3000}
            rows={5}
            required
          />
        </label>

        <label className="form-field">
          <span>Price</span>
          <input
            name="price"
            type="number"
            value={form.price}
            onChange={handleChange}
            min="0"
            step="0.01"
            placeholder="799"
            required
          />
        </label>

        <label className="form-field">
          <span>Compare-at price</span>
          <input
            name="compareAtPrice"
            type="number"
            value={form.compareAtPrice}
            onChange={handleChange}
            min="0"
            step="0.01"
            placeholder="999"
          />
        </label>

        <label className="form-field">
          <span>Stock quantity</span>
          <input
            name="stock"
            type="number"
            value={form.stock}
            onChange={handleChange}
            min="0"
            step="1"
            placeholder="25"
            required
          />
        </label>

        <label className="form-field">
          <span>Category</span>
          <input
            name="category"
            value={form.category}
            onChange={handleChange}
            placeholder="clothing"
          />
        </label>

        <label className="form-field form-field--wide">
          <span>Image URL</span>
          <input
            name="imageUrl"
            type="url"
            value={form.imageUrl}
            onChange={handleChange}
            placeholder="https://example.com/product.jpg"
          />
        </label>

        <label className="checkbox-field form-field--wide">
          <input
            name="isActive"
            type="checkbox"
            checked={form.isActive}
            onChange={handleChange}
          />
          <span>
            Show this product in the storefront
          </span>
        </label>
      </div>

      <div className="product-form__actions">
        <button
          type="submit"
          className="button button--primary"
          disabled={saving}
        >
          {saving
            ? "Saving..."
            : isEditing
              ? "Update product"
              : "Create product"}
        </button>

        {onCancel && (
          <button
            type="button"
            className="button button--ghost"
            onClick={onCancel}
          >
            Cancel
          </button>
        )}
      </div>
    </form>
  );
};

export default ProductForm;
